const D = { wear: .55, scale: 1, energy: .6, density: .5, hue: 214, speed: 1, x: .5, y: .46, alpha: 1, style: 'poured', act: 'drift', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const wear=cl(P.wear,0,1.4), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4);
const en=cl(P.energy,0,1)*(.5+.6*K.intensity);
const T=K.t*spd, H=md(P.hue,360);
const hz=cl(P.y,.26,.74)*Hh, cx=cl(P.x,.05,.95)*W, gH=Math.max(24,Hh-hz);

S.bass=(S.bass||0)*.84+(A.bass||0)*.16;
S.tre=(S.tre||0)*.84+(A.treble||0)*.16;
const kick=Math.min(1,K.pulse*(.5+.5*K.intensity)+S.bass*.7);
const glow=(.4+.6*cl(P.energy,0,1))*(.55+.55*K.intensity);

const wet=(sty==='wet'), terr=(sty==='terrazzo'), blue=(sty==='blueprint');
const yOf=t=>hz+Math.pow(cl(t,0,1),1.7)*gH;
const hwOf=t=>W*(.06+cl(t,0,1)*1.5)*.5*sc;

// ---- scroll: integrate real seconds so the slab never re-phases ----
if(S.pt==null||K.t<S.pt) S.pt=K.t;
const dt=cl(K.t-S.pt,0,.1); S.pt=K.t;
let sp=spd*(.42+.5*K.intensity);
if(act==='haul') sp*=1.7+1.1*kick; else if(act==='settle') sp*=.30+.55*(.5+.5*Math.sin(T*.037));
S.scroll=(S.scroll||0)+dt*sp*.28;
const scroll=S.scroll;

// ---- the slab itself: graded pour + trowel swirl + aggregate (cached, below the horizon only)
const bkey=W+'x'+Hh+'|'+sty+'|'+P.seed+'|'+Math.round(H)+'|'+Math.round(P.y*24)+'|'+Math.round(sc*8)+'|'+Math.round(wear*5)+'|'+Math.round(dens*5);
if(!S.base||S.bk!==bkey){
  const g=(S.base&&S.base.width===W&&S.base.height===Hh)?S.base:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR=54;
  for(let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR); let h,s,b;
    if(blue){ h=md(H+6,360); s=62; b=9+9*t; }
    else if(terr){ h=md(H+150,360); s=6; b=44+26*Math.pow(t,1.1); }
    else if(wet){ h=H; s=14-6*t; b=15+30*Math.pow(t,1.3); }
    else { h=H; s=9-3*t; b=30+30*Math.pow(t,1.15); }
    g.fill(h,s,cl(b,3,92),100); g.rect(0,y-1,W,(y2-y)+2); }
  // trowel swirl: broad arcs the float left in the wet pour
  if(!blue){ g.noFill();
    for(let i=0;i<Math.round(22+dens*22);i++){ const t=.06+fr(i*7)*.94, y=yOf(t), hw=hwOf(t);
      const rr=hw*(.10+fr(i*7+1)*.5), a0=fr(i*7+2)*TAU;
      g.strokeWeight(Math.max(1,gH*.004*t)); g.stroke(H,terr?4:8,fr(i*7+3)>.5?(terr?92:74):(terr?30:26),terr?9:13);
      g.arc(cx+(fr(i*7+4)*2-1)*hw, y, rr*2, rr*2*.30, a0, a0+1.4+fr(i*7+5)*2.4); }
    g.noStroke(); }
  // aggregate: the stone in the mix, exposed by wear
  const NA=Math.round((terr?520:260)+wear*340+dens*160);
  for(let i=0;i<NA;i++){ const t=.06+Math.pow(fr(i*3),.7)*.94, y=yOf(t), hw=hwOf(t);
    const x=cx+(fr(i*3+1)*2-1)*hw, sz=gH*(terr?.010:.004)*(.3+t*1.5)*(1+fr(i*3+2));
    if(blue){ g.fill(md(H+4,360),50,60,10); }
    else if(terr){ const hh=[md(H+150,360),md(H+16,360),md(H+186,360),md(H+66,360)][i&3];
      g.fill(hh, fr(i*3+3)>.62?46:9, 34+fr(i*3+4)*58, 62); }
    else { g.fill(H, 7, fr(i*3+3)>.5?(58+fr(i*3+4)*30):(16+fr(i*3+4)*16), 30+fr(i*3+5)*34); }
    g.push(); g.translate(x,y); g.rotate(fr(i*3+5)*TAU); g.ellipse(0,0,sz*2.1,sz*1.2); g.pop(); }
  // pitting / spall scars
  if(!blue){ const NP=Math.round(wear*46);
    for(let i=0;i<NP;i++){ const t=.14+fr(i*11)*.86, y=yOf(t), hw=hwOf(t);
      const x=cx+(fr(i*11+1)*2-1)*hw, sz=gH*.008*t*(1+fr(i*11+2)*2.4);
      g.fill(H,10,14,44); g.ellipse(x,y,sz*2.4,sz*1.2);
      g.fill(H,5,86,26); g.ellipse(x,y-sz*.42,sz*2.0,sz*.6); } }
  // horizon haze where the slab runs out of light
  g.push(); g.blendMode(BLEND);
  for(let i=0;i<8;i++){ const r=(8-i)*gH*.035;
    g.fill(blue?md(H+6,360):H, blue?54:12, blue?10:(wet?16:30), 9);
    g.rect(0,hz-r*.10,W,r); }
  g.pop();
  S.base=g; S.bk=bkey; }
image(S.base,0,0);

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
dc.save(); dc.beginPath(); dc.rect(0,hz-1,W,Hh-hz+1); dc.clip();

// ---- longitudinal control joints: sawcuts converging on the vanishing point ----
const NJ=Math.round(3+dens*7);
strokeCap(SQUARE);
for(let k=0;k<=NJ;k++){
  const s=(k-NJ/2)*(2.1/NJ);
  const x0=cx+s*hwOf(.02), x1=cx+s*hwOf(1);
  strokeWeight(Math.max(1,gH*(blue?.004:.006)));
  stroke(blue?md(H+2,360):H, blue?40:8, blue?70:(terr?96:14), blue?52:(terr?60:60)*al);
  line(x0,yOf(.02),x1,yOf(1));
  if(!blue){ strokeWeight(Math.max(1,gH*.0025)); stroke(H,4,terr?40:80,26*al);
    line(x0+2,yOf(.02),x1+gH*.012,yOf(1)); }
}

// ---- transverse joints scrolling toward the viewer ----
const NR=Math.round(5+dens*9);
for(let r=0;r<=NR+1;r++){
  const t=(r-(scroll%1))/NR; if(t<=.012||t>1) continue;
  const y=yOf(t), hw=hwOf(t);
  strokeWeight(Math.max(1,gH*(blue?.0035:.007)*(.2+t)));
  stroke(blue?md(H+2,360):H, blue?40:8, blue?72:(terr?96:13), (blue?54:64)*al*(.35+.7*t));
  line(cx-hw,y,cx+hw,y);
  if(!blue){ strokeWeight(Math.max(1,gH*.003*(.2+t))); stroke(H,4,terr?46:82,(22+16*t)*al);
    line(cx-hw,y-gH*.004*t,cx+hw,y-gH*.004*t); }
}

// ---- the crack network: hairlines opened by frost and load ----
const NCK=Math.round(4+wear*24);
noFill();
for(let i=0;i<NCK;i++){
  let s=(fr(i*13)*2-1)*1.05, t=((fr(i*13+1)-scroll*.62)%1+1)%1;
  if(t<.05) continue;
  const dirS=(fr(i*13+2)-.5)*1.5, dirT=(fr(i*13+3)-.5)*.5;
  strokeWeight(Math.max(.8,gH*.0035*t*(.4+wear)));
  stroke(blue?md(H+4,360):H, blue?46:6, blue?78:10, (blue?46:70)*al*(.3+.7*t));
  beginShape();
  for(let k=0;k<=8;k++){
    const f=k/8;
    const ss=s+dirS*f*.5+Math.sin(f*7+i)*.05, tt=cl(t+dirT*f*.28,.02,1);
    vertex(cx+ss*hwOf(tt), yOf(tt));
  }
  endShape();
  if(fr(i*13+4)>.55){ // a branch splits off it
    strokeWeight(Math.max(.7,gH*.0022*t)); beginShape();
    for(let k=0;k<=5;k++){ const f=k/5;
      const ss=s+dirS*.25+(fr(i*13+5)-.5)*f*.7, tt=cl(t+dirT*.14+f*.10,.02,1);
      vertex(cx+ss*hwOf(tt), yOf(tt)); }
    endShape(); }
}
noStroke();

// ---- oil, water and rust staining soaked into the pour ----
if(!blue){
  dc.globalCompositeOperation='multiply';
  const NST=Math.round(2+wear*9);
  for(let i=0;i<NST;i++){
    const s=(fr(i*17)*2-1)*.95, t=((fr(i*17+1)-scroll*.62)%1+1)%1; if(t<.06) continue;
    const y=yOf(t), hw=hwOf(t), x=cx+s*hw;
    const rr=gH*(.03+fr(i*17+2)*.14)*t*(.5+wear);
    const hh=[md(H+2,360),md(H+150,360),md(H-190,360)][i%3];
    const rg=dc.createRadialGradient(x,y,0,x,y,Math.max(2,rr*1.6));
    rg.addColorStop(0,'rgba(20,22,26,'+(0.42*al).toFixed(3)+')');
    rg.addColorStop(.6,'rgba(46,44,40,'+(0.16*al).toFixed(3)+')');
    rg.addColorStop(1,'rgba(255,255,255,0)');
    dc.fillStyle=rg; dc.beginPath(); dc.ellipse(x,y,rr*1.7,rr*.6,0,0,TAU); dc.fill();
  }
  dc.globalCompositeOperation=oldOp;
}

// ---- wet slab: standing water, mirrored sheen and rings on the bass ----
if(wet){
  dc.globalCompositeOperation='lighter';
  const NPD=Math.round(3+dens*7);
  for(let i=0;i<NPD;i++){
    const s=(fr(i*19)*2-1)*.9, t=((fr(i*19+1)-scroll*.62)%1+1)%1; if(t<.08) continue;
    const y=yOf(t), hw=hwOf(t), x=cx+s*hw, rr=gH*(.04+fr(i*19+2)*.13)*t;
    const lg=dc.createLinearGradient(x,y-rr*.6,x,y+rr*.6);
