    lg.addColorStop(.5,'rgba(180,215,255,'+(0.10*glow*al).toFixed(3)+')');
    lg.addColorStop(1,'rgba(255,255,255,0)');
    dc.fillStyle=lg; dc.beginPath(); dc.ellipse(x,y,rr*2,rr*.62,0,0,TAU); dc.fill();
    const ph=((T*.5+fr(i*19+3))%1);
    dc.strokeStyle='rgba(200,228,255,'+(0.22*(1-ph)*glow*al*(.3+kick)).toFixed(3)+')';
    dc.lineWidth=Math.max(1,gH*.002);
    dc.beginPath(); dc.ellipse(x,y,rr*2*ph,rr*.62*ph,0,0,TAU); dc.stroke();
  }
  dc.globalCompositeOperation=oldOp;
}

