dc.globalCompositeOperation='lighter';
const th=Math.sin(T*.043)*1.12+.34*Math.sin(T*.11)+.18*Math.sin(T*.0233);
const LL=(gH*3+W);
for(let i=0;i<3;i++){
  const dw=(.30-i*.085)*(1+.25*Math.sin(T*.067));
  const a1=th-dw, a2=th+dw;
  const c=blue?'rgba(120,200,255,':'rgba(255,246,226,';
  fill(0,0,0,0);
  dc.fillStyle=c+((0.014+0.026*glow)*al).toFixed(4)+')';
  dc.beginPath(); dc.moveTo(cx,hz);
  dc.lineTo(cx+Math.sin(a1)*LL, hz+Math.cos(a1)*LL);
  dc.lineTo(cx+Math.sin(a2)*LL, hz+Math.cos(a2)*LL);
  dc.closePath(); dc.fill();
}
dc.globalCompositeOperation=oldOp;

// ---- grit blowing across the slab ----
dc.globalCompositeOperation=blue?'source-over':'lighter';
const NG=Math.round(24+dens*54);
noStroke();
for(let i=0;i<NG;i++){
  const t=.10+fr(i*23)*.90, y=yOf(t), hw=hwOf(t);
  const lane=fr(i*23+1);
  const s=((lane+(scroll*.6+T*.05)*(.3+.7*fr(i*23+2)))%1)*2-1;
  const x=cx+s*hw;
  fill(blue?md(H+4,360):H, blue?30:6, blue?80:96, Math.min(40,(6+26*t)*(.4+.9*glow)*al));
  ellipse(x, y+Math.sin(T*1.1+i)*gH*.005*t, gH*.0035*(.4+t*2.4)*(1+.5*S.tre), gH*.0025*(.4+t*1.6));
}
dc.globalCompositeOperation=oldOp;

// ---- polish: the slab keeps a low sheen right where the light lands ----
if(terr||wet){
  dc.globalCompositeOperation='lighter';
  const sx=cx+Math.sin(th)*gH*1.1, sy=hz+gH*.72;
  const rr=gH*(.5+.12*Math.sin(T*.053));
  const rg=dc.createRadialGradient(sx,sy,0,sx,sy,rr);
  rg.addColorStop(0,'rgba(255,250,238,'+(0.05*glow*al).toFixed(4)+')');
  rg.addColorStop(1,'rgba(255,250,238,0)');
  dc.fillStyle=rg; dc.fillRect(sx-rr,sy-rr,rr*2,rr*2);
  dc.globalCompositeOperation=oldOp;
}

